use std::fs

struct Parser {
    toks: Vec<string>,
    pos: int,
    out: Vec<string>,
    bad: bool,
}

impl Parser {
    fn peek(self) -> string {
        if self.pos < self.toks.len() as int {
            self.toks[self.pos as usize]
        } else {
            ""
        }
    }

    fn expr(self) {
        self.term()
        while !self.bad && (self.peek() == "+" || self.peek() == "-") {
            let op = self.peek()
            self.pos += 1
            self.term()
            self.out.push(op)
        }
    }

    fn term(self) {
        self.pw()
        while !self.bad && (self.peek() == "*" || self.peek() == "/") {
            let op = self.peek()
            self.pos += 1
            self.pw()
            self.out.push(op)
        }
    }

    fn pw(self) {
        self.atom()
        if !self.bad && self.peek() == "^" {
            self.pos += 1
            self.pw()
            self.out.push("^")
        }
    }

    fn atom(self) {
        let t = self.peek()
        if t == "(" {
            self.pos += 1
            self.expr()
            if self.peek() == ")" {
                self.pos += 1
            } else {
                self.bad = true
            }
        } else if t.len() > 0 && t[0..1] >= "0" && t[0..1] <= "9" {
            self.out.push(t)
            self.pos += 1
        } else {
            self.bad = true
        }
    }
}

fn tokenize(line: string) -> Vec<string> {
    let mut res: Vec<string> = []
    let mut cur = ""
    for c in line.chars() {
        if c >= '0' && c <= '9' {
            cur = cur + c.to_string()
        } else {
            if cur.len() > 0 {
                res.push(cur)
                cur = ""
            }
            if c == ' ' || c == '\t' || c == '\r' {
            } else if c == '+' || c == '-' || c == '*' || c == '/' || c == '^' || c == '(' || c == ')' {
                res.push(c.to_string())
            } else {
                res.push("?")
            }
        }
    }
    if cur.len() > 0 {
        res.push(cur)
    }
    res
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim().len() == 0 {
            continue
        }
        let mut p = Parser { toks: tokenize(line), pos: 0, out: [], bad: false }
        p.expr()
        if p.bad || p.pos < p.toks.len() as int {
            println("error")
        } else {
            println(p.out.join(" "))
        }
    }
}

